def para(label,text):
 p=r.d.add_paragraph();p.add_run(label+' ').bold=True;p.add_run(text);return p
def j(v):return ', '.join(v)
def unique(v):return sorted(set(v))
def brfr(b):return [f for f in FR if b in f['br']]
def refs(fs,key):return unique(x for f in fs for x in f[key])
def tab(c,h,rows,w=None):
 if h[0] in ('Scenario','Issue'): rows=[(row[0].split()[0],*row[1:]) for row in rows]
 r.table(c,h,rows,w)
 for row in r.d.tables[-1].rows:
  for c in row.cells:c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def split_ids(ids,size=5):return [ids[i:i+size] for i in range(0,len(ids),size)]

r.h('Introduction')
r.h('Purpose and intended use',2)
r.p('This document establishes DailyKhata\'s formal requirements baseline for the project team, supervisor and assessors. It translates the approved problem, user needs and scope into eight business requirements, 69 functional requirements and 26 non-functional requirements. The catalogue supports architecture, database and interface design, implementation and acceptance testing. It specifies intended behaviour; it does not assert that the application has been built or tested. [G1-G5, D1, D2, A3]')
r.p('All 38 canonical scope capabilities are represented, including all 27 Must Have capabilities. Optional requirements retain their approved Should Have or Could Have status. The baseline is feasible as a bounded four-student integration project using existing OCR and language-model capabilities, subject to the dependency and acceptance-target reviews recorded later in this document.')
r.h('Project overview and problem',2);r.p(DEFINITION);r.p(PROBLEM)
r.h('Product boundary',2)
r.p('The primary users are homemakers and household budget managers, university students and salaried professionals in Pakistan. A single account holder records personal or household expenses. Small shopkeepers are secondary direct users for petty cash and supplier expenses. Family members may review information with the account holder or receive a user-exported summary; they do not gain household roles, invitations or collaborative editing rights. The system is mobile-first and targets ordinary Android-class devices. [D1, D2, G1]')
r.p('The current product combines reviewed receipt digitisation, manual and text-based cash entry, an expense ledger, internal accounting mappings, semantic product classification, item-level price history, summaries and a read-only AI Financial Assistant. Voice, bilingual localisation, export, custom labels, extra views and image archive remain optional. Detailed exclusions and future scope appear later and are not current requirements.')
r.h('Requirement conventions',2)
tab('Requirement identifiers and interpretation',['Identifier or term','Meaning'],[
('BR-001 onwards','Business outcome and its rationale; not a list of implementation features.'),('FR-GROUP-001 onwards','Observable functional behaviour. Each record has a priority, source chain and acceptance criterion.'),('NFR-GROUP-001 onwards','Quality condition, measurement method and scope source.'),('EV, DR, SC and SS','Existing D2 evidence, preliminary candidate and approved scope identifiers. D3 links rather than replaces them.'),('Shall','Normative behaviour for a requirement selected for delivery. A Should Have or Could Have statement does not become mandatory because it uses shall.'),('Acceptance target','A proposed FYP gate to review before testing, not a measured performance result.'),('Source and inference','Evidence means what the supplied source reports. Project-team analysis and D3 elaborations are labelled separately.')],[1.4,4.62])
r.p('IDs are persistent. Later deliverables may elaborate them, attach design or test references and record status. Retired IDs must remain in change history and must not be reused. A substantive change records old wording, new wording, reason, source authority, affected IDs and reviewer decision. This document introduces no new major feature and makes no silent change to D1 or D2.')

r.h('Requirements engineering approach')
r.h('Sources and authority',2)
r.p('The workspace was recursively inventoried before writing. The current governance files, D1 v2.0 and D2 v2.0 were read completely, together with the five-page official D3 brief, original deliverables, task sheets, Design Thinking slides and supporting notes. The reference folder contains no additional research. No source code, raw survey dataset, interview transcript or observation log was available. The 17 input files recorded for this task remain byte-for-byte unchanged.')
tab('Source authority and use',['Level','Source','Use in D3'],[
('1','Current governance [G1-G5]','Scope, terminology, priorities, reconciliation decisions and document standard.'),('2','D1 v2.0 [D1]','Project definition, target audience, design personas, problems and market rationale.'),('3','D2 v2.0 [D2]','EV evidence register, DR candidates, stakeholders and elicitation limitations.'),('4','Official D3 brief [A3]','Business, functional and quality requirements, traceability and validation.'),('5','Historical D1 and D2 [H1-H2]','Provenance only where current baseline has reconciled contradictions.'),('6','Task sheets and Design Thinking [M1-M3]','Assignment context and separation of observation from interpretation.'),('7','External security guidance [X1-X3]','Limited quality-control rationale, never authority for new product features.')],[.45,2.05,3.52])
r.h('Elicitation and analysis',2)
r.p('D2 reports interviews, observation and existing-system examination. This D3 performs documentary analysis of those findings rather than claiming additional stakeholder work. Capture friction supports BR-001; difficulty reconstructing coherent histories supports BR-002 and BR-003. Product semantics, the full internal Chart of Accounts and assistant breadth also rely explicitly on the approved scope. The source chain remains visible even where fieldwork does not establish a capability. [D2, EV-01 to EV-07]')
r.p('Analysis separated outcomes from behaviour, decomposed receipt processing from review and commitment, and distinguished local category labels from categories and accounting accounts. Repeated concepts were consolidated: saved-data maintenance is defined once in the ledger group, then reused by summary, price and assistant requirements. Dependencies were checked so no Must Have requirement needs an optional capability. The internal model was checked before Word authoring for unique IDs, coverage, valid references, duplicate statements and priority conflicts.')
r.h('Classification and prioritisation',2)
tab('Priority rules inherited from governance',['Priority','Delivery interpretation','Rule for dependencies'],[
('Must Have','Minimum successful DailyKhata FYP.','Cannot depend on a Should Have or Could Have feature.'),('Should Have','Intended but may be deferred with a recorded reason.','May depend on core functionality or other selected Should Have features.'),('Could Have','Optional if time and technical capacity permit.','May depend on a selected higher-priority capability; record the dependency.'),('Future Scope','Potential later work, not a current commitment.','No current acceptance requirement is created.'),('Out of Scope','Explicitly excluded from the current project.','Mentioned only to establish the boundary.')],[1,2.6,2.42])
r.p('BR-001 includes optional voice as an additional route to a core outcome. This does not make voice Must Have. Likewise, Should Have presentation outcomes can draw on core data without requiring optional screens for core assistant answers. Shared quality controls apply to optional functionality only when that functionality is implemented. NFR-COMP-002, the dedicated localisation quality requirement, is itself Should Have.')
r.h('Validation and traceability method',2)
r.p('The traceability chain is problem, stakeholder need, evidence or documentary authority, DR candidate, BR outcome, FR behaviour, NFR quality condition and acceptance test. Every FR identifies its source, scope, business outcome and quality links. The four traceability matrices provide reverse lookup. Validation here means requirements inspection and model checks; user trials, software tests, student verification and supervisor endorsement are planned acceptance activities, not completed research. [A3]')

r.h('Stakeholder and evidence foundation')
r.h('Canonical user profiles',2)
tab('Canonical personas inherited from D1 and D2',['Persona','Age and role','Classification'],[(p[0]+' '+p[1],p[2]+'; '+p[3],p[4]) for p in PERSONAS],[1.45,3.12,1.45])
r.p('Ayesha needs household visibility and receipt capture; Hamza needs a short cash-entry path; Bilal needs searchable monthly records. Usman reuses the expense workflow for petty cash and supplier purchases. Zubair is a secondary beneficiary of shared information, with age not recorded. These are design profiles, not five verified interview participants. Usman\'s canonical design age is 41 under DEC-01; the original D2 participant age of 46 remains an unresolved source discrepancy. Bilal and Zubair are not reported interviewees. [G3-G5, D1, D2]')
r.h('Other stakeholders and responsibilities',2)
tab('Stakeholder interests and requirements responsibilities',['Stakeholder','Classification and interest','Engagement'],[
('Four project students','Internal developers and analysts; implementation feasibility and traceability.','Verify source interpretation, maintain requirement IDs, implement and record tests.'),('Nouman Ali','Internal academic supervisor; scope and academic quality.','Review requirements and proposed targets; endorsement is not yet recorded.'),('Family beneficiaries and advisers','Secondary information users; understandable expense summaries.','Review user-shared output without privileged application roles.'),('Selected OCR AI and storage providers','Conditional external technical dependencies; service constraints and data processing.','Review interfaces, cost, retention and failure behaviour before selection.'),('Bank and payment partners','Future stakeholders only.','No current integration or delivery dependency.')],[1.35,2.55,2.12])
r.h('Evidence register and limitations',2)
tab('Preserved D2 evidence register',['ID','Reported finding','Provenance and limitation'],[(k,*v) for k,v in EV.items()],[.65,2.55,2.82])
r.p('D1 also supplies the original assistant and target-market intent, especially for DR-08. The qualitative evidence supports design rationale, not market size, population prevalence or quantified benefit. No fabricated participant, survey result, quotation, benchmark or user test is included. The historical competitor comparison is not evidence about current products. The original statement about a customer paying is retained only as cash-capture context and never becomes sales or payment scope.')

r.h('Business requirements')
r.h('Business goals and catalogue',2)
r.p('The outcomes concern reduced recording effort, coherent records, spending understanding, product comparison, privacy and ordinary-device use. Optional outcomes improve presentation and recording habits. Success indicators below describe observable outcomes to evaluate, not claimed improvements already measured. The related scope and functional IDs make each outcome operational.')
for bid,title,statement,obj,why,stake,priority,success in BR:
 r.h(title,3);para(bid+' | '+priority,statement)
 para('Objective and rationale:',obj+' '+why)
 para('Stakeholders and source:',stake+'. '+j(refs(brfr(bid),'evidence'))+'; '+j(refs(brfr(bid),'dr'))+'. DR-08 additionally retains original D1 [H1] intent.' if bid=='BR-003' else stake+'. '+j(refs(brfr(bid),'evidence'))+'; '+j(refs(brfr(bid),'dr'))+'.')
 para('Success indicator:',success)
 para('Scope and downstream behaviour:',j(unique(refs(brfr(bid),'scope')+(['SC-30'] if bid=='BR-006' else [])))+'. '+j([f['id'] for f in brfr(bid)])+'.')
r.h('Business requirement analysis',2)
r.p('The first six outcomes define the minimum product purpose. BR-007 and BR-008 add optional benefits without changing the intended market. No requirement promises measured financial savings, user retention or a market share. A saving suggestion is useful only when its arithmetic and assumptions are visible; the user remains responsible for deciding what to do. An expense record can be internally coherent even when the user has not recorded all real-world spending, so the assistant must distinguish recorded spending from total actual spending.')

r.h('Functional requirements')
r.h('Shared workflow and data rules',2)
r.p('A capture route produces a draft. Extraction and interpretation propose values. The account holder reviews required fields, resolves inconsistent totals and confirms categories, then explicitly commits the expense. Only an active committed expense participates in summaries and price history. Every protected operation inherits the authentication boundary. The common actor, preconditions, trigger and rationale stated for each subsystem apply to its records; each requirement supplies its own behaviour, acceptance oracle and failure path.')
tab('Controlled D3 elaborations and interpretation rules',['Rule','Normative interpretation and reason'],[
('E-01 Identity and dates','Stable opaque identifiers distinguish account, expense, item, category and account mapping. Use the expense calendar date for summaries and a separate creation timestamp. Resolve relative dates using Asia/Karachi. Today may be a visible default in manual entry; missing receipt dates require confirmation. This formalises retrospective entry.'),
('E-02 Amounts and currency','Baseline expenses are positive PKR amounts represented exactly to two decimal places. A manually entered total is permitted when OCR fails. Refunds, income workflows, foreign-currency conversion and scheduled future expenses are not added by this specification.'),
('E-03 Receipt reconciliation','The payable transaction total is authoritative after review. Allocate it across the categorised purchase lines, including explicit user-reviewed discount, tax or rounding adjustments. Keep adjustments distinct from products and exclude them from product-price history. Block saving until the allocations equal the total; do not invent a missing product to balance it.'),
('E-04 Counting and categories','For an itemised receipt, category totals sum its allocations; for an unitemised expense, its single allocation equals the total. Never sum both parent and line totals. The transaction primary category supports display and search; a category filter also matches a line allocation. It does not replace mixed-item allocations.'),
('E-05 Product quantities','Keep purchased count, pack size, unit price and line total distinct. Unknown quantity is not silently one. Convert known compatible units, such as g to kg, and show the comparison basis. Separate brands and pack identities even under the same canonical product type.'),
('E-06 Corrections and deletion','Preserve original OCR text alongside corrected values while a record exists. Deleting the expense removes its financial content under NFR-PRIV-003; source preservation does not mean retaining deleted content forever. Ordinary history excludes deleted records. Corrections invalidate dependent calculated results.'),
('E-07 Account framework','Maintain the five conventional account types: asset, liability, equity, income and expense. The FYP exposes only expense-management workflows; cash is an asset account. Recognising an account type does not create sales, payroll or full financial-statement functionality. Final hierarchy and codes remain architecture decisions.'),
('E-08 Settings and credentials','A display name and default summary month give a bounded interpretation of basic profile and settings. Login identifier format and credential rules are documented at implementation review; if passwords are managed locally, use at least 12 characters and permit at least 64. These proposed details do not add social login or account administration.'),
('E-09 Draft lifetime','Core draft recovery is limited to the current open authenticated session. Surviving application restart without connectivity is the Could Have offline-draft feature. Pending drafts never count as expenses. Optional archive retention does not make permanent image storage core.'),
('E-10 Optional data output','CSV and/or PDF means at least one format, not both. If CSV is selected, user-supplied text beginning with formula-control characters must be exported as inert text and fields escaped correctly. Household output remains an account-holder-controlled selection, not a shared-account service.')],[.85,5.17])
r.p('These are D3 project-team elaborations of approved capabilities, not additional interview findings. Numerical and platform choices are proposed FYP acceptance boundaries to confirm before implementation. Any change to them must use the persistent IDs and change-control rule. None changes a source persona, capability priority or current-versus-future decision.')
for group,meta in GROUPS.items():
 title,actor,pre,trigger,why,nfr=meta
 r.h(title,2)
 para('Context:',why)
 para('Actor and preconditions:',actor+' '+pre)
 para('Trigger and common flow:',trigger+' The specific requirement below defines the observable result; invalid operations follow its failure path and do not imply a successful save.')
 fs=[f for f in FR if f['group']==group]
 for f in fs:
  r.h(f['title'],3)
  para(f['id']+' | '+f['priority'],f['statement'])
  para('Trace and rationale:',j(f['br'])+'; '+j(f['scope'])+'; '+j(f['dr'])+'; '+j(f['evidence'])+'. '+('Original D1 [H1] also supports assistant intent. ' if 'DR-08' in f['dr'] else '')+'This behaviour implements the subsystem purpose above and the linked business outcome.')
  para('Acceptance and expected result:',f['acceptance'])
  para('Alternative or failure:',f['failure'])
  para('Dependencies and quality:',(j(f['dependencies']) if f['dependencies'] else 'No earlier functional service required; authentication infrastructure is needed')+'. '+j(f['nfr'])+'.')
r.p('Dependency references identify service contracts rather than mandatory screen order. OCR can receive a camera photograph or an uploaded image. Product and assistant records reuse the authoritative ledger and calculation contracts. Optional features never sit on the dependency path needed to complete the Must Have capture-to-summary workflow.')

r.h('Non functional requirements')
r.h('Measurement conditions and status',2)
r.p('All numerical thresholds, test-set sizes, device versions, session limits and retention intervals in this section are Proposed acceptance targets for the FYP. They were selected through requirements analysis, not measured in existing fieldwork. Students and supervisor should confirm them using an early pilot. They become delivery gates when this baseline is accepted; any revised target requires a recorded change rather than a silent relaxation. All described tests remain to be executed.')
tab('Acceptance environments and fixtures',['Fixture','Definition and measurement control'],[
('T1 Ordinary device and network','Android 11-class device, 4 GB RAM, at least a 360 CSS-pixel-equivalent viewport; one newer Android version. Choose and record native or mobile-web delivery. Test network: at least 10 Mbps down, 2 Mbps up and approximately 100 ms round-trip latency. Record actual conditions, device, build, cold/warm state and provider configuration.'),
('T2 Capacity and ledger','Ten isolated test accounts, each with 1000 active expenses and up to ten line items per receipt. Run 20 minutes at one request per account every five seconds, 20 percent writes and the remainder history, search and summary reads. Verify all committed records and report rejected requests separately.'),
('T3 Security and privacy','Two accounts with deliberately overlapping merchant and product names but distinct private records; expired sessions, altered object identifiers, malicious filenames, invalid images and cross-account assistant prompts. Include receipt text attempting to override retrieval instructions.'),
('T4 Financial oracle','Controlled PKR records with known dates, categories, product identities and expected arithmetic. Include empty data, two periods, zero baseline, repeated expenses, mixed receipt, missing unit, corrected item and deleted transaction. Reference acceptance scenarios in the validation section.'),
('T5 Receipt extraction','Twenty consented or synthetic printed receipts, clearly labelled by origin, with 3-12 purchase lines each, legible English or Latin-script text, varied layouts and known payable totals. Use two independent annotation passes and reconcile differences. Keep several blurred/cropped images separate for failure-path tests. Urdu OCR is not implied by Urdu interface support.'),
('T6 Prospective user and language review','Five recruited trial users spanning the three primary groups for core tasks; a competent bilingual reviewer for optional Urdu output. Record consent, task script, actual outcomes and defects. These participants have not yet been recruited or tested.')],[.9,5.12])
r.p('Performance measurements separate the application\'s processing time, external provider latency and total visible waiting time. A timeout is a bounded failure response, not a promise of successful OCR or AI completion in 60 seconds. The controlled calculation suite verifies defined answers; it cannot establish perfect general language-model accuracy. Supported-receipt fidelity is measured before correction, while successful end-to-end recording also requires a usable correction path.')
NAMES={'PERF':'Performance','SEC':'Security','PRIV':'Privacy','USE':'Usability','REL':'Reliability','DATA':'Data integrity','COMP':'Compatibility and localisation quality','MAINT':'Maintainability','SCAL':'Academic capacity'}
for g,title in NAMES.items():
 r.h(title,2)
 for n in [x for x in NFR if x['group']==g]:
  r.h(n['title'],3);para(n['id']+' | '+n['priority'],n['statement'])
  para('Source and rationale:',j(n['scope'])+'; approved scope [G1, EV-07] and D2 quality expectations. '+('External guidance is supporting security practice, not a new stakeholder finding. ' if g=='SEC' else '')+'This condition constrains the linked functional behaviours in the traceability matrix.')
  para('Verification:',n['test'])
r.p('No uptime percentage, million-user scale, banking-grade security claim or vendor-specific stack is required. Protected financial storage and correct calculations are mandatory; the selected implementation must demonstrate them in the defined finite tests. If the team cannot meet a proposed target, the result is a documented acceptance issue requiring review, not permission to remove its underlying Must Have capability.')

r.h('Requirement prioritisation')
counts=collections.Counter(f['priority'] for f in FR);nc=collections.Counter(n['priority'] for n in NFR)
tab('Catalogue totals by priority',['Priority','BR','FR','NFR','Scope capabilities'],[(p,sum(b[6]==p for b in BR),counts[p],nc[p],sum(s[2]==p for s in SCOPE)) for p in ['Must Have','Should Have','Could Have']],[1.7,.7,.7,.7,2.22])
r.p('Implement and test one complete Must Have path first: authenticate, capture or enter, review, classify, reconcile, save, retrieve and summarise. Extend this path with product history and the assistant without postponing those core capabilities into optional scope. Optional voice and localisation can be evaluated independently once their shared core contracts work. Defer optional work explicitly if it threatens completion of the Must Have baseline.')
r.p('Scope aliases are unchanged: SS-01 means SC-10, SS-02 means SC-29 and SS-07 means SC-28. They are traceability aliases and are not additional counted capabilities. Dedicated comparison views are Should Have; conversational period comparisons remain Must Have. Automatic recurring transaction creation, predictive anomaly detection and advanced autonomous recommendations remain future scope.')

