r.h('Appendix glossary')
tab('Canonical terminology and abbreviations',['Term','Meaning in this specification'],[
('DailyKhata','The personal expense-management application defined by the approved scope.'),('OCR','Optical character recognition; proposes text from receipt images.'),('Receipt digitisation','Capture and transformation of a receipt into reviewable structured expense data.'),('Expense transaction','One confirmed expense with an owner, date, amount and categorised accounting allocations.'),('Line item','An individual purchase line within a receipt; distinct from the transaction total.'),('Automatic categorisation','A machine proposal for transaction or line-item category, subject to user confirmation or correction.'),('Expense category','User-understandable spending classification; its label is separate from its identity.'),('Chart of Accounts','Internal register of stable accounting accounts, types and references.'),('Semantic product classification','Mapping to canonical product types while preserving source text, brand and product identity.'),('Item-level price history','Historical recorded product prices with purchase context and comparable quantity where available.'),('AI Financial Assistant','Read-only conversational analysis of the current user\'s authorised DailyKhata records.'),('Localisation','Optional adaptation of interface language and presentation, including potential Urdu RTL support.'),('PKR and Rs.','Pakistani rupee; the baseline currency. Amounts use exact two-decimal representation.'),('RTL','Right-to-left text and interface presentation where required for Urdu.'),('FYP and SRS','Final Year Project and Software Requirements Specification.'),('Draft and commitment','An unconfirmed working record and the explicit transition to one saved expense. Drafts do not contribute to financial totals.')],[1.6,4.42])
r.d.core_properties.subject='DailyKhata authoritative requirements baseline'
# Check all authored text before serialisation.
alltext='\n'.join(p.text for p in r.d.paragraphs)+'\n'+'\n'.join(c.text for t in r.d.tables for row in t.rows for c in row.cells)
assert '\u2014' not in alltext
r.finish()
(WORK/'authored_text.txt').write_text(alltext,encoding='utf-8')
